package dev.recipeeditor.exporters;

import java.nio.file.*;
import java.util.*;
import dev.recipeeditor.core.ResourceLocation;
import dev.recipeeditor.recipeengine.editor.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class ExportPlannerTest {
    @TempDir Path root;
    @Test void autoPrefersDatapackButExposesAlternativesAndPerRecipeChoice()throws Exception {final var f=new ExportFixtures(root);final var c=f.create("crafttweaker:new",f.raw);final var ctx=f.context(List.of(c),ExportFormat.AUTO);final var p=f.planner.plan(f.request(ctx));assertTrue(p.valid());assertEquals(ExportFormat.DATAPACK,p.recipes().getFirst().format());assertEquals(3,p.recipes().getFirst().alternatives().size());assertTrue(p.diagnostics().stream().anyMatch(d->d.code()==ExportDiagnostic.Code.EXPORT_AMBIGUOUS_CHOICE));final var manual=f.planner.plan(new ExportRequest(ctx,Set.of(c.id()),Map.of(c.id(),ExportFormat.KUBEJS),List.of()));assertTrue(manual.valid());assertEquals(ExportFormat.KUBEJS,manual.recipes().getFirst().format());}
    @Test void autoRoutesDeletionAndNeverSilentlyDropsUnsupported()throws Exception {final var f=new ExportFixtures(root);final var base=f.original("test:base",f.raw);final var c=f.change(base,RecipeChangeType.DELETE,"");final var ctx=f.context(List.of(c),List.of(base),ExportFormat.AUTO,Map.of("kubejs","2001.6.4-build.120"),List.of(),OverwritePolicy.REFUSE);final var p=f.planner.plan(f.request(ctx));assertTrue(p.valid(),p.diagnostics().toString());assertEquals(ExportFormat.KUBEJS,p.recipes().getFirst().format());final var invalid=f.plan(List.of(f.create("test:unknown","{\"type\":\"unknown:recipe\"}"),f.create("test:new",f.raw)),ExportFormat.AUTO);assertFalse(invalid.valid());assertEquals(2,invalid.recipes().size());}
    @Test void absentDependenciesLeaveDeletionUnsupported()throws Exception {final var f=new ExportFixtures(root);final var base=f.original("test:base",f.raw);final var ctx=f.context(List.of(f.change(base,RecipeChangeType.DELETE,"")),List.of(base),ExportFormat.AUTO,Map.of(),List.of(),OverwritePolicy.REFUSE);assertFalse(f.planner.plan(f.request(ctx)).valid());}
    @Test void profileMismatchAndUnsafeOutputAreRejected()throws Exception {final var f=new ExportFixtures(root);final var ctx=f.context(List.of(f.create("test:new",f.raw)),ExportFormat.AUTO);final var wrong=new ExportProfile("testprofile","Wrong",f.target,ExportFormat.AUTO,OverwritePolicy.REFUSE,true,"1.21","FORGE");final var bad=new ExportContext(ctx.modpack(),ctx.originals(),ctx.savedChanges(),ctx.projectFile(),wrong,List.of(),Set.of(),false);assertTrue(f.planner.plan(f.request(bad)).diagnostics().stream().anyMatch(d->d.code()==ExportDiagnostic.Code.EXPORT_VERSION_MISMATCH));assertThrows(IllegalArgumentException.class,()->new ExportProfile("testprofile","Bad",f.target,ExportFormat.AUTO,OverwritePolicy.OWNED_UNCHANGED,false,"1.20.1","FORGE"));}
    @Test void selectedIdsAreExactAndUnchangedCopyIsExplicit()throws Exception {final var f=new ExportFixtures(root);final var c=f.create("test:new",f.raw);final var base=f.original("test:base",f.raw);final var ctx=f.context(List.of(c),List.of(base),ExportFormat.DATAPACK,Map.of(),List.of(),OverwritePolicy.REFUSE);assertFalse(f.planner.plan(new ExportRequest(ctx,Set.of(),Map.of(),List.of())).valid());final var p=f.planner.plan(new ExportRequest(ctx,Set.of(),Map.of(),List.of(base)));assertTrue(p.valid(),p.diagnostics().toString());assertEquals(List.of(base.id()),p.recipes().stream().map(r->r.change().id()).toList());assertEquals(1,ctx.savedChanges().changes().size());assertFalse(f.planner.plan(new ExportRequest(ctx,Set.of(ResourceLocation.parse("test:unsaved")),Map.of(),List.of())).valid());}
    @Test void thousandCreatesUseOneGroupedScript()throws Exception {final var f=new ExportFixtures(root);final var changes=java.util.stream.IntStream.range(0,1000).mapToObj(i->f.create("test:batch/recipe_"+i,f.raw)).toList();final var p=f.plan(changes,ExportFormat.KUBEJS);assertTrue(p.valid(),p.diagnostics().toString());assertEquals(1000,p.recipes().size());assertEquals(1,p.files().size());}
    @Test void changedOriginalOnDiskAndBlockedChangesPreventExport()throws Exception {final var f=new ExportFixtures(root);final var base=f.original("test:base",f.raw);final var c=f.change(base,RecipeChangeType.DELETE,"");final var ctx=f.context(List.of(c),List.of(base),ExportFormat.KUBEJS,Map.of("kubejs","2001.6.4-build.120"),List.of(),OverwritePolicy.REFUSE);Files.writeString(f.source.resolve(base.source().internalPath()),"{}");assertFalse(f.planner.plan(f.request(ctx)).valid());}
}
